(() => {
  'use strict';
  const C=window.QUEST_CURRICULUM,D=window.QUEST_DATA;
  const text=v=>typeof v==='string'?v.slice(0,4000):'';
  const iso=v=>typeof v==='string'&&Number.isFinite(Date.parse(v))?new Date(v).toISOString():'';
  const object=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{};
  const defaults=()=>({week:1,pace:8,units:{},labs:{},project:{},reviews:{},diagnosis:''});
  const draftFields=['prediction','explain','operate','compare','transfer','result','limits','change','evidence','decision','next','answer'];
  const modes=['independent','assisted','replay'];
  function clean(raw){
    raw=object(raw);const out=defaults();out.week=Number.isInteger(raw.week)?Math.max(1,Math.min(12,raw.week)):1;out.pace=raw.pace===4?4:8;out.diagnosis=text(raw.diagnosis);
    for(const [key,ids] of [['units',Object.keys(C.units)],['labs',C.labs.map(x=>x.id)],['project',C.stages.map(x=>x.id)]]){
      for(const id of ids){const src=object(raw[key]?.[id]);if(!Object.keys(src).length)continue;const dst={};for(const f of draftFields)if(typeof src[f]==='string')dst[f]=text(src[f]);dst.mode=modes.includes(src.mode)?src.mode:'assisted';dst.savedAt=iso(src.savedAt);dst.checks=Array.isArray(src.checks)?[...new Set(src.checks.filter(x=>Number.isInteger(x)&&x>=0&&x<4))]:[];out[key][id]=dst;}
    }
    for(const id of Object.keys(C.units)){const src=object(raw.reviews?.[id]);if(!iso(src.due))continue;out.reviews[id]={due:iso(src.due),stage:Number.isInteger(src.stage)?Math.max(0,Math.min(4,src.stage)):0,answer:text(src.answer),history:Array.isArray(src.history)?src.history.slice(-50).filter(x=>iso(x.at)&&['again','ready'].includes(x.result)).map(x=>({at:iso(x.at),result:x.result,answer:text(x.answer)})):[]};}
    return out;
  }
  function merge(a,b){const out=clean(a),incoming=clean(b);for(const k of ['units','labs','project','reviews'])for(const [id,v] of Object.entries(incoming[k]))if(!out[k][id])out[k][id]=v;if(!out.diagnosis)out.diagnosis=incoming.diagnosis;return out;}
  let H;
  const current=()=>H.get().learning;
  const esc=v=>H.esc(v);
  const title=id=>D.chapters.flatMap(x=>x.lessons).find(x=>x.id===id)?.title||id;
  const link=(href,label,primary=false)=>`<a class="button ${primary?'':'secondary'} small" href="${href}">${esc(label)} ↗</a>`;
  const list=items=>`<ul class="growth-list">${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
  const date=v=>v?new Date(v).toLocaleDateString('zh-CN'):'';
  const due=()=>Object.entries(current().reviews).filter(([,r])=>r.stage<4&&Date.parse(r.due)<=Date.now());
  const entry=(kind,id)=>current()[kind][id]||{};
  const modeName=m=>({independent:'独立完成 · 自述',assisted:'借助提示完成 · 自述',replay:'模拟 / 回放练习'}[m]||'尚未记录');
  function field(kind,id,name,label,placeholder='写下自己的判断、实际结果或仍未解决的问题。',value){return `<label class="field-label" for="g-${kind}-${id}-${name}">${esc(label)}</label><textarea id="g-${kind}-${id}-${name}" data-growth-field="${name}" data-kind="${kind}" data-id="${id}" maxlength="4000" placeholder="${esc(placeholder)}">${esc(value??entry(kind,id)[name]??'')}</textarea>`;}
  function mode(kind,id){const value=entry(kind,id).mode||'assisted';return `<label class="field-label" for="g-mode-${kind}-${id}">这份记录怎样完成？</label><select id="g-mode-${kind}-${id}" class="select" data-growth-mode data-kind="${kind}" data-id="${id}">${modes.map(m=>`<option value="${m}" ${value===m?'selected':''}>${modeName(m)}</option>`).join('')}</select>`;}
  function head(k,t,p){return H.intro(k,t,p);}
  function saveButton(kind,id,label){return `<div class="button-row growth-gap"><button class="button" data-growth="save" data-kind="${kind}" data-id="${id}">${label}</button><span class="small-text" id="g-save-${kind}-${id}">${entry(kind,id).savedAt?'上次提交：'+date(entry(kind,id).savedAt)+' · 内容未外部评审':'输入自动保存为草稿；提交后保留证据日期'}</span></div>`;}
  function banner(){const s=current();return `<section class="growth-banner"><div><span class="eyebrow">YOUR LONG GAME · 第二期</span><h2>沿一条主线，把知识做扎实。</h2><p>18 个深度单元 · 8 个实操任务 · 一个持续迭代的工单预审项目</p><span class="small-text">当前第 ${s.week} 阶段 · ${due().length} 项到期复测 · 单选题记录为热身</span></div><div class="button-row">${link('#path','继续十二周路线',true)}${link('#review','复测与证据')}</div></section>`;}
  function panel(html){H.main.innerHTML=html;}
  function renderPath(){
    const s=current(),w=C.weeks[s.week-1];
    panel(head('LEARNING JOURNEY','十二周，做深一个项目。','每周学机制、做实验、留证据。进度由你决定，完成阅读不会自动证明能力。')+`<div class="growth-two"><section class="growth-card"><span class="eyebrow">THIS WEEK · 第 ${s.week} 阶段</span><h2>${esc(w[0])}</h2><p>${esc(w[4])}</p><div class="button-row">${link('#unit/'+w[1][0],'进入深度单元',true)}${link('#practice/'+w[2],'本周实操')}${link('#project','项目 '+w[3])}</div><p class="small-text growth-gap">表达练习：${esc(w[5])}</p></section><aside class="growth-card"><h3>选择可持续的投入</h3><label class="field-label" for="growth-pace">每周可用时间</label><select id="growth-pace" class="select"><option value="8" ${s.pace===8?'selected':''}>8 小时 · 约 12 周</option><option value="4" ${s.pace===4?'selected':''}>4 小时 · 约 24 周</option></select><p class="small-text">${s.pace===8?'原理 2h · 实操 4h · 复测 1h · 岗位/表达 1h':'原理 1h · 实操 2h · 复测 0.5h · 表达 0.5h。每阶段约两周，保留独立操作。'}</p><a class="text-button" href="#bridge">Python / API 动手桥梁 →</a><a class="text-button" href="#review">${due().length?'有 '+due().length+' 项到期复测':'查看复测与能力证据'} →</a></aside></div><details class="growth-card"><summary>起点诊断：先用自己的话回答三件事</summary><p>① 给一个任务分配规则、SQL 与模型。② 描述你怎样验证一个回答有依据。③ 解释一条 API 请求与返回。暂时不会的写出来，后续用实验补齐。</p><label class="field-label" for="growth-diagnosis">我的起点（自动保存）</label><textarea id="growth-diagnosis" maxlength="4000">${esc(s.diagnosis)}</textarea><p class="small-text">诊断用于选择学习起点，不产生招聘适配分数。</p></details><div class="section-heading"><h2>每阶段都有一个产出</h2><span class="small-text">可自由进入，手动标记当前阶段</span></div><div class="growth-weeks">${C.weeks.map((week,i)=>`<article class="growth-card ${s.week===i+1?'growth-active':''}"><span class="eyebrow">${s.pace===8?'WEEK '+(i+1):'第 '+(i*2+1)+'—'+(i*2+2)+' 周'} · ${week[3]}</span><h3>${esc(week[0])}</h3><p>${esc(week[4])}</p><div class="growth-links">${week[1].map(id=>`<a href="#unit/${id}">${esc(title(id))} ↗</a>`).join('')}</div><div class="button-row growth-gap">${link('#practice/'+week[2],'做本期实验')}<button class="text-button" data-growth="week" data-id="${i+1}">${s.week===i+1?'当前阶段 ✓':'设为当前'}</button></div></article>`).join('')}</div><section class="growth-card growth-gap"><h2>完成十二个阶段之后</h2><p>接下来用三个四周周期继续：先依据反馈改进主项目，再从行业应用、Agent 平台、预测决策中选一条支线，最后做跨场景验证。每轮保留一个问题、一次对照、一个坏例和一次复测。</p><p>每月只核验与当前任务相关的课程与岗位变化，记录来源和日期。已有 SKILL 支持整理与评审，学习时间优先用于尚未掌握的机制和操作。</p></section>`);
  }
  function renderUnit(id){
    const u=C.units[id];if(!u){location.hash='path';return;}
    const saved=entry('units',id);
    panel(`<a class="text-button back" href="#path">← 返回学习路线</a>`+head('DEEP LEARNING UNIT',esc(title(id)),u.goal)+`<div class="growth-two"><article class="growth-card"><span class="pill">先修：${esc(u.prereq)}</span><h2 class="growth-gap">01 · 先预测，再看解释</h2><p>${esc(u.predict)}</p>${field('units',id,'prediction','我的预测','先写原因，再展开下方示范。')}<details class="growth-reading"><summary>02 · 原理与完整示范</summary>${u.reason.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="feedback"><strong>推演一个具体例子</strong><p>${esc(u.worked)}</p></div></details><h2 class="growth-gap">03 · 独立变式与反例</h2><p>${esc(u.variation)}</p><div class="feedback warning"><strong>故意制造一次失败</strong><p>${esc(u.failure)}</p></div>${link('#practice/'+u.lab,'打开配套实操',true)}<h2 class="growth-gap">04 · 留下四种能力证据</h2><p class="small-text">先写自己的解释，其他证据可以逐步补充。每项记录表示你提交了证据，不等于已通过独立评审。</p>${C.levels.map(([key,name,hint])=>field('units',id,key,name+'证据',key==='transfer'?u.transfer:hint)).join('')}${mode('units',id)}${saveButton('units',id,'提交记录，安排复测')}<h2 class="growth-gap">05 · 检查与迁移</h2>${list(u.criteria)}<p><strong>陌生情境：</strong>${esc(u.transfer)}</p></article><aside><section class="growth-card"><h3>这次学习怎么走</h3><p>预测 → 机制 → 示例 → 独立变式 → 找错 → 证据 → 复测</p><p class="small-text">分两次，每次约 30—45 分钟；配套实验另安排 60—120 分钟。复杂操作先跟做、再改输入、最后解释变化。</p><a class="text-button" href="#bridge">需要补动手基础？ →</a></section><section class="growth-card"><h3>定向阅读</h3><p>${esc(u.reading)}</p><a class="text-button" href="${u.source}" target="_blank" rel="noopener noreferrer">打开原始资料 ↗</a><p class="small-text">资料核验：${C.edition}。只读与本任务相关部分。概念通过实验再确认。</p></section><section class="growth-card"><h3>我的记录状态</h3>${C.levels.map(([key,name])=>`<p class="small-text">${name}：${(saved[key]||'').trim().length>=20?'已有文字证据 · 待复核':'待补充'}</p>`).join('')}<a class="text-button" href="#review">看复测安排 →</a></section></aside></div>`);
  }
  function kitLinks(){return `<div class="button-row">${link('./materials/ai-quest-learning-kit.zip','下载完整实操包',true)}${link('./materials/README.md','先读运行说明')}</div><p class="small-text">Python 3 标准库，无需安装依赖即可跑计算、关键词/TF-IDF 检索与模拟工具。真实模型和语义 Embedding 为本机可选模式，需要你已有的兼容 API 环境。所有业务材料为合成数据。</p>`;}
  function renderPractice(id){
    const lab=C.labs.find(x=>x.id===id);
    if(!id){panel(head('PRACTICE FIELD','每次动手，都留下一个发现。','八个实操任务配材料、步骤、指标和验收产出。已有参数模拟继续作为热身。')+`<section class="growth-card">${kitLinks()}<a class="text-button" href="#labs">打开两个热身模拟 →</a></section><div class="growth-weeks">${C.labs.map((l,i)=>`<article class="growth-card"><span class="eyebrow">LAB ${String(i+1).padStart(2,'0')} · ${l.minutes} MIN</span><h2>${esc(l.name)}</h2><span class="pill outline">${esc(l.mode)}</span><p class="growth-gap">${esc(l.deliver)}</p><div class="button-row">${link('#practice/'+l.id,'接下实验',true)}<span class="small-text">${entry('labs',l.id).savedAt?'已有实验记录':'待独立探索'}</span></div></article>`).join('')}</div>`);return;}
    if(!lab){location.hash='practice';return;}
    panel(`<a class="text-button back" href="#practice">← 返回实操任务</a>`+head('LAB CASE FILE',esc(lab.name),lab.mode+' · '+lab.minutes+' 分钟')+`<div class="growth-two"><article class="growth-card"><h2>材料与起步</h2><p>${esc(lab.material)}</p>${kitLinks()}<label class="field-label">解压后，在材料包目录运行</label><pre class="growth-code">${esc(lab.command)}</pre><p class="small-text">先确认 Python 能运行；若命令不可用，按 README 替换为本机 Python 路径。这里显示的是你将执行的步骤，不表示网页已代你完成。</p>${field('labs',id,'prediction','先写实验假设','改变哪个条件？预计哪个结果变化？为什么？')}<h2 class="growth-gap">动手顺序</h2><ol class="growth-list">${lab.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="feedback"><strong>怎样测量</strong><p>${esc(lab.measure)}</p></div>${id==='rag-detective'?detective():''}${id==='retrieval-real'||id==='rag-detective'?`<section class="growth-card growth-gap"><h3>浏览器热身：真实字符检索</h3><p class="small-text">直接对 12 份材料计算字符二元组交集分数；不是向量模型，也不生成答案。先观察，再到材料包比较 TF-IDF。</p><label class="field-label" for="g-query">问题</label><input class="select" id="g-query" value="质保内设备故障缺处理照片能否通过"><label class="field-label" for="g-at">业务查询日期</label><input class="select" id="g-at" type="date" value="2026-10-15"><label class="growth-check"><input id="g-valid" type="checkbox">按该日期过滤有效条款</label><button class="button small" data-growth="search">运行字符检索</button><div id="g-results" aria-live="polite"></div></section>`:''}<h2 class="growth-gap">实验记录</h2>${field('labs',id,'result','实际运行与结果','写明输入、参数、两组结果和运行日期。可以粘贴输出摘要；不填密钥。')}${field('labs',id,'limits','失败与局限','至少一个失败、无改善结果或未验证条件。')}${field('labs',id,'transfer','迁移判断',lab.transfer)}${mode('labs',id)}${saveButton('labs',id,'提交实验记录')}<p class="small-text growth-gap">验收产出：${esc(lab.deliver)}。提交只确认记录完整，不自动判定内容正确。</p></article><aside><section class="growth-card"><h3>先修与回顾</h3>${link('#unit/'+lab.unit,title(lab.unit))}<p class="growth-gap">完整示范 → 改一个关键条件 → 独立变式。请先预测再运行，保留预期与实际不一致的地方。</p></section><section class="growth-card"><h3>支持强度如实记录</h3><p>独立完成：自己决定关键参数并解释结果。借助提示：根据帮助完成。模拟/回放：只验证流程，不作为真实模型效果。</p><a class="text-button" href="#project">把发现带回主项目 →</a></section></aside></div>`);
  }
  function detective(){return `<details class="growth-reading"><summary>完整示范：从引用找到首次偏离</summary><p>假设当前查询是 2026-10-15，系统找到“仅文字说明即可通过”的照片规则。先打开材料，发现该版本在 2026-09-01 已失效。</p><p>第一处偏离发生在适用性过滤。保持问题和排序方法不变，只增加有效日期条件，再检查当前条款是否进入候选。不能只改最终回答措辞。</p><p>再把查询日期改成 2026-08-15，此时旧规则可能适用。简单删除全部旧版本会破坏历史查询。最后用保留题和无答案题检查，分别报告证据与结论。</p><p>这段是推演示范，不是你的实测结果。实际排序由当前材料和算法运行得到；把你的输出记录在下方。</p></details>`;}
  function renderProject(){panel(head('ONE PROJECT, MANY ITERATIONS','把工单预审，做成你的作品。','从规则基线到有据建议，再到工具协作和业务验证。一个项目，六段可复查的学习证据。')+`<section class="growth-card"><p>用户：运维审核员。任务：核对材料与规范，形成有出处的待补清单，由审核员确认。已有个人 SKILL 支持需求和评审；本项目练习新增业务能力。</p><p class="small-text">先用合成样例。真实业务试用需要可用材料、明确范围和独立判断条件；没有条件则记录为任务演练。</p></section>${C.stages.map(st=>`<section class="growth-card"><span class="eyebrow">${st.id} · 第 ${st.weeks} 阶段周</span><h2>${esc(st.name)}</h2><p>${esc(st.prompt)}</p><div class="growth-two"><div><h3>这一阶段提交什么</h3>${list(st.deliver)}<div class="feedback"><strong>验收依据</strong><p>${esc(st.gate)}</p></div>${link('#practice/'+st.lab,'进入配套实操')}</div><div>${field('project',st.id,'evidence','证据与产出','记录文件名、运行结果摘要和日期；勿填公司敏感数据。')}${field('project',st.id,'decision','我的决策与依据','我选了什么、放弃了什么，什么证据会让我改选？')}${field('project',st.id,'next','未解决与下一步')}${mode('project',st.id)}${saveButton('project',st.id,'提交阶段证据')}</div></div></section>`).join('')}<section class="growth-card"><h2>每四周一次答辩</h2><p>第 4 周：解释一个提示对照。第 8 周：演示完整流程及一个故障。第 12 周：改变约束后作选择。均带上实际结果和未解决问题。</p>${link('#interview','进入面试营地')}</section>`);}
  function renderBridge(){panel(head('HANDS-ON BRIDGE','从 SQL 出发，跨过第一次动手。','用本地合成材料学习 Python、JSON、API。先能看懂并改动小步骤，再组合流程。')+`<section class="growth-card">${kitLinks()}<h2 class="growth-gap">四次短练习</h2>${list(['列表/字典：把 SQL 的行理解为一条记录，字段名对应 JSON 的键。打开 tickets.json，找到 ticket_id 和 description。','条件/函数：找出缺少描述的工单；说明空字符串、null 与数字 0 的区别。把判断写成可重复调用的函数。','文件与批量：运行 inspect，解释它如何读取 CSV 并遍历行。改一个合成时间字段再运行，比较输出。','请求与异常：运行 model --mode replay，找到请求体、结果和检查字段；再阅读 live 分支，分清超时、结构错误和业务错误。'])}<pre class="growth-code">python --version
python practice.py inspect
python practice.py model --mode replay --prompt basic</pre><p>完成标准：你能自己改一个输入、运行、找到对应输出，并解释为什么改变。暂时无需学习框架或部署。</p><h3>真实调用准备好后</h3><p>README 列出接口类型、环境变量和命令。密钥只在本机环境配置，不填写到网页或上传 GitHub。没有调用环境时，回放仍可练数据处理；把“真实模型运行”保留为待补。</p>${link('#practice/api-batch','第一次批量调用',true)}<p class="growth-gap"><a href="https://docs.python.org/3/tutorial/" target="_blank" rel="noopener noreferrer">Python 官方教程</a>按字典、函数、文件/JSON、异常四部分查阅。教程假设已有基本编程理解，配合本站的业务例子使用。</p></section>`);}
  function reviewQuestion(id,stage){const u=C.units[id];return [u.predict,u.variation,u.transfer,'结合自己的运行结果解释：'+u.failure][Math.min(3,stage)];}
  function renderReview(){const s=current(),entries=Object.entries(s.reviews);panel(head('RECALL & EVIDENCE','隔一段时间，再把它讲清楚。','首次提交解释后安排第 1、7、21、45 天复测。答不出就补薄弱点；无需连续签到。结果由你自评，不等于独立验收。')+`<div class="growth-two"><section class="growth-card"><h2>${due().length} 项到期复测</h2><p>先闭卷作答，再查看验收要点。如果借助提示才能完成，选择“需要补练”。提前练习会保存回答，但不会推进复测日期。</p><p class="small-text">这是起始复习节奏，不保证对所有知识最优；迟到后按实际复测日安排下一间隔。只在打开网页时计算到期，不发送后台通知。</p></section><section class="growth-card"><h2>中断后，15 分钟恢复</h2><p>先看最近一条证据，闭卷回答一个问题，再改一个小条件。保留历史记录，下一次从当前阶段继续。</p>${link('#path','回到当前阶段')}</section></div>${entries.length?entries.map(([id,r])=>`<section class="growth-card"><span class="eyebrow">${r.stage>=4?'四轮复测记录齐备':'第 '+(r.stage+1)+' 轮 · '+date(r.due)+(Date.parse(r.due)<=Date.now()?' · 已到期':' · 尚未到期')}</span><h2>${esc(title(id))}</h2><p>${esc(reviewQuestion(id,r.stage))}</p>${field('reviews',id,'answer','闭卷回答','先写自己的解释，再看要点。',r.answer)}<details class="growth-reading"><summary>查看验收要点</summary>${list(C.units[id].criteria)}<p class="small-text">不能独立解释时标记补练，不用猜一个“通过分数”。</p></details><div class="button-row growth-gap"><button class="button small" data-growth="recall" data-id="${id}" data-result="ready" ${r.stage>=4?'disabled':''}>独立完成，记录自评</button><button class="button secondary small" data-growth="recall" data-id="${id}" data-result="again">需要补练，明天再来</button>${link('#unit/'+id,'补薄弱点')}</div>${r.history.length?`<details class="growth-reading"><summary>查看 ${r.history.length} 条历史回答</summary>${r.history.slice().reverse().map(h=>`<p class="small-text">${date(h.at)} · ${h.result==='ready'?'自评独立完成':'需要补练'}</p><div class="saved-note">${esc(h.answer)}</div>`).join('')}</details>`:''}</section>`).join(''):`<section class="growth-card"><h2>从一条解释开始</h2><p>进入一个深度单元，提交自己的解释，即可开始复测安排。旧的单选题完成记录不会自动转换为能力证明。</p>${link('#unit/methods','进入第一个单元',true)}</section>`}<section class="growth-card"><h2>能力证据簿</h2><p class="small-text">文字记录只是待复核的证据。四种能力分别呈现，不计算招聘成功率或统一“掌握分”。</p><div class="table-wrap"><table class="data-table"><thead><tr><th>知识单元</th>${C.levels.map(x=>`<th>${x[1]}</th>`).join('')}<th>完成方式</th></tr></thead><tbody>${Object.keys(C.units).map(id=>`<tr><td><a href="#unit/${id}">${esc(title(id))}</a></td>${C.levels.map(([k])=>`<td>${(s.units[id]?.[k]||'').trim().length>=20?'有记录':'待补'}</td>`).join('')}<td>${modeName(s.units[id]?.mode)}</td></tr>`).join('')}</tbody></table></div></section>`);}
  function journalSummary(){const s=current();return `<section class="growth-card"><h2>深度学习与项目证据</h2><p>${Object.values(s.units).filter(x=>x.savedAt).length} 个单元已提交 · ${Object.values(s.labs).filter(x=>x.savedAt).length} 份实操记录 · ${Object.values(s.project).filter(x=>x.savedAt).length} 份项目阶段记录 · ${due().length} 项到期复测</p><div class="button-row">${link('#review','复测与证据')}${link('#project','主项目')}${link('#practice','实操任务')}</div><p class="small-text">这些记录包含在顶部导出备份中；输入自动保存草稿，提交与独立评审分开。</p></section>`;}
  async function search(){const target=document.getElementById('g-results');if(!target)return;target.textContent='正在读取合成材料…';try{const r=await fetch('./materials/documents.json');if(!r.ok)throw Error('材料读取失败');const docs=await r.json();const q=document.getElementById('g-query').value.trim(),at=document.getElementById('g-at').value,valid=document.getElementById('g-valid').checked;if(!q||!at){target.textContent='请填写问题和查询日期。';return;}const grams=s=>{const a=[...s.replace(/\s/g,'')];return new Set(a.slice(0,-1).map((x,i)=>x+a[i+1]));};const tokens=grams(q);const ranked=docs.filter(d=>!valid||(d.valid_from<=at&&(!d.valid_to||at<d.valid_to))).map(d=>({...d,score:[...grams(d.title+d.text)].filter(x=>tokens.has(x)).length})).filter(d=>d.score>0).sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id)).slice(0,3);if(!target.isConnected)return;target.innerHTML=`<p class="small-text">${ranked.length} 条候选 · 查询时点 ${esc(at)} · 得分为交集数，不是正确率</p>${ranked.map(d=>`<article class="retrieval-item"><strong>${esc(d.id)} · ${esc(d.title)} · ${d.score} 分</strong><p>${esc(d.text)}</p><small>${esc(d.valid_from)} 至 ${esc(d.valid_to||'持续有效')}（结束日不含）</small></article>`).join('')||'<p>没有匹配候选。请检查材料是否覆盖问题。</p>'}`;}catch{if(target.isConnected)target.textContent='材料暂未加载，请下载实操包在本机运行。';}}
  function init(h){H=h;document.addEventListener('input',e=>{const el=e.target,s=current();if(el.id==='growth-diagnosis'){s.diagnosis=el.value;H.save();return;}if(!el.dataset.growthField)return;const {kind,id,growthField:f}=el.dataset;if(!Object.hasOwn(s,kind)||!Object.hasOwn(s[kind],id)){if(!['units','labs','project'].includes(kind))return;s[kind][id]={mode:'assisted'};}s[kind][id][f]=el.value;H.save();});document.addEventListener('change',e=>{const el=e.target;if(el.id==='growth-pace'){current().pace=Number(el.value)===4?4:8;H.save();renderPath();}if(el.hasAttribute('data-growth-mode')){const {kind,id}=el.dataset;if(!current()[kind][id])current()[kind][id]={};current()[kind][id].mode=el.value;H.save();}});document.addEventListener('click',e=>{const el=e.target.closest('[data-growth]');if(!el)return;const {growth:action,kind,id,result}=el.dataset;const s=current();if(action==='week'){s.week=Number(id);H.save();renderPath();window.scrollTo(0,0);}if(action==='search')search();if(action==='save'){const record=entry(kind,id);const required=kind==='units'?['explain']:kind==='labs'?['prediction','result','limits']:['evidence','decision'];if(required.some(k=>(record[k]||'').trim().length<20)){H.toast('请先补齐每项必填记录（至少 20 字）：'+(kind==='units'?'自己的解释':kind==='labs'?'假设、实际结果、失败与局限':'证据、决策'));return;}record.savedAt=new Date().toISOString();s[kind][id]=record;if(kind==='units'&&!s.reviews[id])s.reviews[id]={due:new Date(Date.now()+86400000).toISOString(),stage:0,answer:'',history:[]};H.save();document.getElementById(`g-save-${kind}-${id}`).textContent='已提交 '+date(record.savedAt)+' · 内容未外部评审';H.toast(kind==='units'?'记录已保存，查看复测页了解下次安排。':'已保存证据；内容正确性仍需核查。');}if(action==='recall'){const r=s.reviews[id];if(!r||(r.answer||'').trim().length<20){H.toast('请先写下至少 20 字的闭卷回答。');return;}if(Date.parse(r.due)>Date.now()&&result==='ready'){H.save();H.toast('练习已保存，尚未到期，复测阶段保持不变。');return;}r.history.push({at:new Date().toISOString(),result,answer:r.answer});r.history=r.history.slice(-50);if(result==='ready'){r.stage=Math.min(4,r.stage+1);const intervals=[1,6,14,24];r.due=new Date(Date.now()+(intervals[r.stage]||45)*86400000).toISOString();}else{r.stage=Math.min(3,r.stage);r.due=new Date(Date.now()+86400000).toISOString();}r.answer='';H.save();renderReview();H.toast('已记录自评，并更新下一次复测安排。');}});}
  const sections={path:'十二周路线',unit:'成长地图',practice:'实操任务',project:'主线项目',review:'复测与证据',bridge:'动手桥梁'};
  function render(route){const [name,id]=route.split('/');if(name==='path')renderPath();if(name==='unit')renderUnit(id);if(name==='practice')renderPractice(id);if(name==='project')renderProject();if(name==='review')renderReview();if(name==='bridge')renderBridge();}
  window.QuestGrowth={defaults,clean,merge,init,render,banner,journalSummary,sections};
})();
